window.VOICE_MODES={"natural": {"label": "App Author voice", "duration": 747.2803333333331, "scenes": [{"id": 0, "start": 0, "end": 20, "kind": "footage", "title": "Real setup demonstration", "kicker": "OPENING • YOUR FOOTAGE", "narration": "Opening footage: actual eGPU connection, external Game Mode, unplug test and return to the handheld. The two waits are visibly accelerated. The opening video plays before the timed narration and can be skipped.", "action": "Reserved footage only. Keep the actual wait visible or mark an edit. Match-cut the handheld silhouette into the app glyph at 00:20. No recreated footage.", "reference": "VID20261109121330.mp4; source/intro-edit-plan.json", "duration": 20, "note": "Actual owner footage • 8x / 10x wait sections labeled"}, {"id": 1, "start": 20, "end": 29.479999999999997, "kind": "hero", "title": "EGPU Buddy", "kicker": "GAME MODE. BIG SCREEN.", "narration": "This is EGPU Buddy. It brings an external graphics card into your Linux handheld’s Game Mode, with the controls right in the Quick Access menu.", "action": "Handheld glyph glides in. Connection draws toward external display. Wordmark settles on the beat.", "reference": "README.md:11–17; plugin handhelds/lenovo-legion-go-2.svg", "duration": 9.479999999999999, "note": "USB4 handheld → powered external GPU → monitor or TV", "speechStart": 20, "speechEnd": 29.2}, {"duration": 23.480000000000004, "kind": "requirements", "title": "The handheld needs USB4", "kicker": "EGPU BUDDY", "narration": "For a USB-connected eGPU, the handheld needs USB4 with PCIe tunneling, or a compatible Thunderbolt port. An ordinary USB-C charging or display port is not enough. Check the handheld, dock and cable. Older proprietary XG Mobile connectors use their own supported path. The tested XG Mobile 2025 uses the USB4 / Thunderbolt route.", "note": "USB-C describes the connector. USB4 / PCIe tunneling supplies the eGPU connection.", "media": null, "reference": "egpu-detect dock classification; TESTED.md XG Mobile 2025; USB4 PCIe requirement", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 2, "start": 29.479999999999997, "end": 52.96, "speechStart": 29.479999999999997, "speechEnd": 52.67999999999999}, {"duration": 17.720000000000006, "kind": "patches", "title": "What had to be fixed", "kicker": "EGPU BUDDY", "narration": "This took more than adding a menu. The NVIDIA driver needs changes so removal does not keep touching hardware that has gone away. Gamescope needs a different scan-out buffer path to fix NVIDIA picture corruption. The app also coordinates Game Mode, screens and audio, with system integration that survives OS updates.", "note": "Patched NVIDIA driver • gamescope scan-out fix • session and audio recovery", "media": null, "reference": "CREDITS.md hot-unplug driver and Game Mode corruption; packaging patches 160,165–167,170", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 3, "start": 52.96, "end": 70.68, "speechStart": 52.96, "speechEnd": 70.4}, {"duration": 21.560000000000002, "kind": "community", "title": "Built on community fixes", "kicker": "EGPU BUDDY", "narration": "The NVIDIA picture work builds on NightHammer1000 and antheas, with the root cause identified by matt-schwartz. The hot-unplug driver work builds on NickNill, bdandy and roger-pmta, plus this project’s removal cleanup patches. Decky supplies the plugin framework. These credits are part of the story, not just the closing card.", "note": "Picture: NightHammer1000 / antheas / matt-schwartz\nDriver: NickNill / bdandy / roger-pmta", "media": null, "reference": "CREDITS.md; upstream NVIDIA PRs #985 and #984", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 4, "start": 70.68, "end": 92.24000000000001, "speechStart": 70.68, "speechEnd": 91.96000000000001}, {"id": 5, "start": 92.24000000000001, "end": 106.12004166666668, "kind": "parts", "title": "Three parts working together", "kicker": "UNDER THE SURFACE", "narration": "There are three parts: a Decky plugin for Game Mode, a desktop app with a tray icon, and the system integration underneath. That last part handles the driver and session setup, so the plugin can control it.", "action": "Three layers build vertically. Use real Decky icon, EGPU icon and source screenshot. Connection particles pass between layers.", "reference": "README.md Features / Install; desktop-app/; plugin src/index.tsx", "duration": 13.88004166666667, "note": "", "speechStart": 92.24000000000001, "speechEnd": 105.84004166666668}, {"id": 6, "start": 106.12004166666668, "end": 140.16008333333335, "kind": "hardware", "title": "Start with tested setups", "kicker": "HARDWARE", "narration": "Testing includes Legion Go 2 with the AORUS RTX 5060 Ti AI Box, Legion Go 1 with an RTX 3080 and AOOSTAR AG03, and ROG Xbox Ally X with XG Mobile 2025. Legion Go S Z1 Extreme is also in testing, including Ming’s Radeon RX 9070 XT setup. The original presentation captured that setup while AMD removal work was still in progress; consult the current release notes for its status. These are reported test combinations, not a blanket compatibility list.", "action": "Actual app glyphs reveal left to right. Pair each with its tested dock and card. Hold final row so combinations are readable.", "reference": "README.md Tested hardware; TESTED.md", "duration": 34.04004166666667, "note": "Legion Go S Z1 Extreme added • AMD removal issue remains open", "speechStart": 106.12004166666668, "speechEnd": 139.88008333333335}, {"duration": 34.28, "kind": "dockgallery", "title": "eGPU docks tested so far", "kicker": "PROJECT TEST HARDWARE", "narration": "The dock list includes the AORUS RTX 5060 Ti AI Box, AOOSTAR AG03 and AG02, ASUS XG Mobile 2025, MINISFORUM DEG2, and a TREBLEET Thunderbolt 3 enclosure. There is also another Intel JHL7440-based Thunderbolt 3 enclosure whose brand and model are not documented. These are project test reports, including testing still in progress. The catalog photographs identify the dock families, not every tester’s exact unit or revision.", "note": "Manufacturer/catalog photos • exact revisions may differ. Testing includes work in progress.", "docks": [{"name": "AORUS RTX 5060 Ti AI BOX", "gpu": "RTX 5060 Ti", "photo": "dock-aorus-user.png", "status": "Tested", "evidence": "README.md / TESTED.md: Legion Go 1 and 2; Bazzite / CachyOS / SteamOS", "original_photo": "Aorus 5060ti ai box.png", "bounds": [402, 16, 420, 744]}, {"name": "AOOSTAR AG03", "gpu": "RTX 3080", "photo": "dock-ag03-cutout.png", "status": "Tested", "evidence": "TESTED.md: Legion Go 1 / SteamOS", "original_photo": "dock-ag03.jpg", "bounds": [126, 19, 1283, 1000]}, {"name": "ASUS XG Mobile 2025", "gpu": "RTX 5070 Ti Laptop GPU", "photo": "xg-mobile-cutout.png", "status": "Tested", "evidence": "TESTED.md: SilverplayerX / ROG Xbox Ally X", "original_photo": "xg-mobile.jpg", "bounds": [22, 103, 1185, 1093]}, {"name": "AOOSTAR AG02", "gpu": "Radeon RX 6800 XT", "photo": "dock-ag02-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: RetroMann / Legion Go 1", "original_photo": "dock-ag02.jpg", "bounds": [107, 59, 1322, 935]}, {"name": "MINISFORUM DEG2", "gpu": "Radeon RX 9070", "photo": "dock-deg2-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: zergpoop / Legion Go 1", "original_photo": "dock-deg2.png", "bounds": [42, 132, 1697, 628]}, {"name": "TREBLEET Thunderbolt 3", "gpu": "Radeon RX 9070 XT", "photo": "dock-trebleet-cutout.png", "status": "Testing in progress", "evidence": "ACTIVE_TASK.md 2026-11-07/08: Ming / Legion Go S Z1E; exact product SKU not recorded; representative brand catalog photo", "original_photo": "dock-trebleet.jpg", "bounds": [48, 50, 1438, 934]}, {"name": "Other JHL7440 TB3 enclosure", "gpu": "Radeon RX 6750 XT", "photo": null, "status": "Model not documented", "evidence": "TESTED.md: Ivan C.nunes / Legion Go 1; Intel JHL7440 identifies controller, not brand/SKU"}], "reference": "README.md Tested hardware; TESTED.md; ACTIVE_TASK.md Ming 2026-11-07/08; asset-sources.json", "action": "Reveal the seven dock entries in a four-column gallery. Keep the unidentified enclosure explicitly unpictured.", "id": 7, "start": 140.16008333333335, "end": 174.44008333333335, "speechStart": 140.16008333333335, "speechEnd": 174.16008333333335}, {"duration": 34.19999999999999, "kind": "gpulist", "title": "GPUs tested and reported", "kicker": "PROJECT TEST HARDWARE", "narration": "The NVIDIA list is RTX 3080, RTX 5060 Ti, and the RTX 5070 Ti Laptop GPU inside XG Mobile 2025. An RTX 4070 has also been reported working by a user, with less complete setup detail. AMD testing includes Radeon RX 6800 XT, RX 6750 XT, RX 9070 and RX 9070 XT. AMD remains beta. No specific Intel eGPU model is documented as tested in this source set.", "note": "Test reports are not a promise for every dock / OS combination.", "reference": "README.md NVIDIA generation paragraph and hardware table; TESTED.md AMD sections; ACTIVE_TASK.md Ming", "action": "Show NVIDIA and AMD lists together; distinguish user-reported RTX 4070 from detailed on-device testing.", "id": 8, "start": 174.44008333333335, "end": 208.64008333333334, "speechStart": 174.44008333333335, "speechEnd": 208.36008333333336}, {"duration": 12.439999999999998, "kind": "glyphcredit", "title": "Device glyphs by Victor Borges", "kicker": "EGPU BUDDY", "narration": "The device-specific handheld outlines come from Victor Borges’s handheld-controller-glyphs project. EGPU Buddy uses those real outlines in its screen picker. Thanks, Victor, for making them available under the MIT license.", "note": "Victor Borges / @victor-borges\ngithub.com/victor-borges/handheld-controller-glyphs", "media": null, "reference": "CREDITS.md handheld outlines; vendored LICENSE; github.com/victor-borges/handheld-controller-glyphs", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 9, "start": 208.64008333333334, "end": 221.08008333333333, "speechStart": 208.64008333333334, "speechEnd": 220.80008333333333}, {"id": 10, "start": 221.08008333333333, "end": 238.160125, "kind": "os", "title": "SteamOS. CachyOS. Bazzite.", "kicker": "LINUX GAME MODE", "narration": "The tested Game Mode systems are SteamOS, the handheld Deckify configuration of CachyOS, and Bazzite’s handheld image, bazzite-deck. NVIDIA is the main supported path. AMD and Intel use a beta path. Check the exact card, dock, device and operating-system combination.", "action": "Official distro marks enter together. Steam logo labeled SteamOS, not a custom SteamOS logo. Beta qualifier stays visible.", "reference": "README.md:15, Tested hardware; TESTED.md AMD / Intel", "duration": 17.08004166666666, "note": "CachyOS: handheld / Deckify\nBazzite: handheld image / bazzite-deck", "speechStart": 221.08008333333333, "speechEnd": 237.880125}, {"id": 11, "start": 238.160125, "end": 256.520125, "kind": "attach", "title": "Connect, then let Game Mode move", "kicker": "THE EVERYDAY FLOW", "narration": "After installation and the required reboot, plugging in the eGPU starts the attach flow. On supported tested setups, Game Mode moves to the external screen and sound follows. The display can go dark briefly during the transition. The timing depends on the device and setup.", "action": "Signal travels from handheld through eGPU. External display illuminates. Small transition label acknowledges brief black screen.", "reference": "README.md Features; original §6; current tested-path qualification", "duration": 18.360000000000014, "note": "A short dark-screen transition can be part of the attach flow.", "speechStart": 238.160125, "speechEnd": 256.240125}, {"id": 12, "start": 256.520125, "end": 273.760125, "kind": "detach", "title": "Safe Detach comes before unplugging", "kicker": "RETURN TO HANDHELD", "narration": "For a planned disconnect, close the game, open EGPU Buddy and choose Safe Detach. Confirm, keep the cable connected, and wait for Game Mode to return to the handheld. Reopen the menu and check that it says it is safe to unplug. That is the normal controlled route.", "action": "Show real main screenshot beside step sequence. Signal fades toward handheld. Cable remains connected until confirmation. No yank demonstration.", "reference": "src/index.tsx Safe Detach confirmation and gameUp guard; ACTIVE_TASK supplied 2026-11-08 AMD detach issue", "duration": 17.24000000000001, "note": "Close game → Safe Detach → wait → read unplug status → unplug", "speechStart": 256.520125, "speechEnd": 273.480125}, {"duration": 25.0, "kind": "recovery", "title": "What if the cable gets pulled?", "kicker": "EGPU BUDDY", "narration": "The patched NVIDIA driver also handles surprise removal. It tracks that the GPU is gone and avoids invalid hardware accesses, while the app brings Game Mode back to the handheld. On tested NVIDIA setups, a yank recovers to a usable handheld in a way similar to Safe Detach, and replugging attaches again. A running game may close. This is recovery support, not a universal guarantee across all cards and docks.", "note": "Patched NVIDIA removal handling + app/session fallback\nTested recovery reaches the handheld again; a running game may close.", "media": null, "reference": "TESTED.md surprise removal table; CREDITS patches160/165–167/170; bdandy NVIDIA PR985", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 13, "start": 273.760125, "end": 298.760125, "speechStart": 273.760125, "speechEnd": 298.48012500000004}, {"id": 14, "start": 298.760125, "end": 318.400125, "kind": "screens", "title": "Choose where Game Mode appears", "kicker": "YOUR SCREENS", "narration": "The screen picker shows connected displays with their names, ports, resolution and refresh rate. The shapes distinguish a handheld, a TV and an ultrawide. Choose a screen to move Game Mode there. The default best-picture setting asks for native resolution and the highest refresh rate. Compatible screens can also wake and switch input automatically.", "action": "Main-page screenshot held large, with a traveling highlight. Device glyph fans into handheld and display choices.", "reference": "README.md Multiple displays / Best picture; src/index.tsx screenIcon / applyBestScreenModes", "duration": 19.639999999999986, "note": "", "speechStart": 298.760125, "speechEnd": 318.12012500000003}, {"id": 15, "start": 318.400125, "end": 331.48016666666666, "kind": "copyback", "title": "The eGPU can render for a small screen", "kicker": "HANDHELD AND XR", "narration": "You can keep the handheld screen while games render on the eGPU. XR glasses connected to the handheld can use the passthrough path too. Compatibility is still being tested, so check the current notes for your glasses and setup.", "action": "Reverse signal route from eGPU to handheld display. XR connection shown as a labeled output, not a universal support badge.", "reference": "src/index.tsx XR connected dialog; supplied ACTIVE_TASK pending AR retest", "duration": 13.08004166666666, "note": "", "speechStart": 318.400125, "speechEnd": 331.2001666666667}, {"id": 16, "start": 331.48016666666666, "end": 351.7601666666667, "kind": "telemetry", "title": "Readings and GPU controls", "kicker": "DETAILS", "narration": "Details shows the GPU, driver, connection and live readings: temperature, power, clocks, memory and load. Available controls include a power limit and clock offset. What you can change depends on the card and install path. The animated example values are illustrations; check the real readings on your device.", "action": "Real Details screenshot moves upward slowly. Telemetry labels animate beside it; no invented FPS or benchmark numbers.", "reference": "README.md GPU details; plugin Details; original §8", "duration": 20.28000000000003, "note": "", "speechStart": 331.48016666666666, "speechEnd": 351.48016666666666}, {"id": 17, "start": 351.7601666666667, "end": 367.4001666666667, "kind": "xg", "title": "XG Mobile gets its own controls", "kicker": "ASUS DOCK", "narration": "On the supported ASUS XG Mobile setup, the plugin and desktop app expose the power target, fan modes, a custom fan curve, dock lighting, and core and memory offsets. These are specific dock controls, shown here with the project’s real interface.", "action": "Official ASUS product photo paired with real XG screenshot. Gentle push in, then fan/light/power labels appear.", "reference": "README.md ASUS XG Mobile; screenshot-xg-mobile.png; ASUS gallery", "duration": 15.639999999999986, "note": "", "speechStart": 351.7601666666667, "speechEnd": 367.1201666666667}, {"id": 18, "start": 367.4001666666667, "end": 383.92016666666666, "kind": "desktop", "title": "The same setup on the desktop", "kicker": "DESKTOP APP", "narration": "Desktop Mode has an EGPU Buddy app and tray icon, with GPU readings, screen selection, power controls, Safe Detach and Re-attach. This screenshot uses an ASUS XG Mobile: the lighting and fan controls shown here are specific to that dock.", "action": "Actual desktop screenshot fills right side. App icon moves down toward an illustrated tray position, labeled schematic.", "reference": "README.md Desktop app / Multiple displays; desktop screenshot", "duration": 16.519999999999982, "note": "Desktop app / tray access\nLighting and fan controls shown: ASUS XG Mobile only", "speechStart": 367.4001666666667, "speechEnd": 383.6401666666667}, {"id": 19, "start": 383.92016666666666, "end": 405.80016666666666, "kind": "experimental", "title": "Optional settings (experimental)", "kicker": "TRY WITH CARE", "narration": "NVIDIA settings adds low latency, V-sync and frame limits. AMD’s Adrenaline Settings adds supported Linux equivalents, with experimental FSR upgrades and Fluid Motion Frames for compatible games. Other opt-in extras include USB4 link checks and LG TV control. The Big Art mode menu fix is for NVIDIA only.", "action": "Three labeled text lanes appear. Experimental label stays on screen. Avoid Windows vendor control-panel screenshots.", "reference": "RELEASE-NOTES.md 0.7.236; README.md NV GPU Buddy; src/index.tsx", "duration": 21.879999999999995, "note": "", "speechStart": 383.92016666666666, "speechEnd": 405.5201666666667}, {"id": 20, "start": 405.80016666666666, "end": 425.1202083333333, "kind": "report", "title": "Save a report for Discord support", "kicker": "DISCORD SUPPORT", "narration": "For help on Discord, open EGPU Buddy and choose Show details. Under Support report, select Save support report to Desktop. Wait for it to finish. Then switch to Desktop Mode and open your Desktop folder. In the Discord support channel, attach the saved report file with a short description of the problem and what you were doing when it happened.", "action": "Highlight the source-rendered Save support report to Desktop button; show the saved file moving from Desktop to a Discord attachment step. Demo file only.", "reference": "capture-sandbox/plugin-source.tsx Support report section, makeReport; user requested Discord support workflow", "duration": 19.32004166666667, "note": "Show details → Support report → Save to Desktop → attach the file in Discord", "speechStart": 405.80016666666666, "speechEnd": 424.8402083333333}, {"id": 21, "start": 425.1202083333333, "end": 444.6802083333333, "kind": "credits", "title": "Built with testers and upstream projects", "kicker": "THANK YOU", "narration": "Thanks to the hardware testers, including SilverplayerX, 1khanfusion, RetroMann, Ivan C.nunes, zergpoop, akamel001 and Ming. Thanks also to Victor Borges for the handheld glyphs, and the projects and patch authors credited earlier. The full list is in CREDITS.md. Next, let’s install the plugin.", "action": "Tester names hold in two columns. Short upstream line, then chapter wipe into how-to. Full attribution in source files.", "reference": "CREDITS.md; original §12", "duration": 19.560000000000002, "note": "Hardware testers + patch authors + Victor Borges / handheld-controller-glyphs", "speechStart": 425.1202083333333, "speechEnd": 444.40020833333335}, {"id": 22, "start": 444.6802083333333, "end": 455.04020833333334, "kind": "tutorial", "title": "Install the Decky plugin", "kicker": "HOW TO • GAME MODE", "narration": "With Decky Loader already installed, we will add the EGPU Buddy plugin from Game Mode, then install its system integration. Those are two separate steps.", "action": "Chapter card with Decky icon and app icon. Two-stage graphic separates plugin from system integration.", "reference": "README.md Install; Decky official README", "duration": 10.360000000000014, "note": "Decky Loader already installed → EGPU Buddy plugin → system integration.", "speechStart": 444.6802083333333, "speechEnd": 454.7602083333333}, {"id": 23, "start": 455.04020833333334, "end": 467.88025, "kind": "prereq", "title": "Before you start", "kicker": "STEP 1 OF 7", "narration": "This tutorial assumes Decky Loader is already installed. Start in Game Mode, with internet and power available. Keep the eGPU unplugged during installation and the reboot afterwards.", "action": "Unplugged cable graphic. Official Decky-on-device image held beside prerequisite. On-screen installer URL decky.xyz.", "reference": "README.md Install; https://github.com/SteamDeckHomebrew/decky-loader#installation", "duration": 12.84004166666665, "media": "decky-general.png", "note": "Decky Loader already installed.\nKeep eGPU unplugged through installation AND reboot.", "speechStart": 455.04020833333334, "speechEnd": 467.60025}, {"duration": 15.95999999999998, "kind": "capture", "title": "1. Enable Decky Developer mode", "kicker": "EGPU BUDDY", "narration": "In Game Mode, open the Quick Access menu and select Decky. Open Decky’s settings, choose General, and turn on Developer mode. The Developer tab becomes available. This is Decky’s setting, not Steam’s separate developer menu.", "note": "Quick Access → Decky → Settings → General\nDeveloper mode: ON", "media": "decky-general.png", "reference": "Actual upstream GeneralSettings component, source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 24, "start": 467.88025, "end": 483.84024999999997, "speechStart": 467.88025, "speechEnd": 483.56025}, {"duration": 15.88004166666667, "kind": "capture", "title": "2. Download the Decky ZIP", "kicker": "EGPU BUDDY", "narration": "The file route avoids typing a long URL. Open the project’s Releases page in a browser. Desktop Mode is the simplest place to do that. Download the EGPU-Buddy-Decky ZIP asset for the current release. Do not choose the dot run desktop installer or GitHub’s source-code ZIP.", "note": "Browser download → EGPU-Buddy-Decky-<version>.zip\nDesktop Mode is simplest; return to Game Mode afterward.", "media": "github-release-actual.png", "reference": "Actual GitHub release page read-only capture; verified release v0.7.242", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 25, "start": 483.84024999999997, "end": 499.72029166666664, "speechStart": 483.84024999999997, "speechEnd": 499.4402916666666}, {"duration": 18.120000000000005, "kind": "capture", "title": "3. Browse to the downloaded ZIP", "kicker": "EGPU BUDDY", "narration": "Return to Game Mode. In Decky settings, open Developer. Under Install Plugin from ZIP File, choose Browse. In the file picker, open your Downloads folder and select the EGPU Buddy Decky ZIP. The file route and URL route install the same plugin.", "note": "Developer → Install Plugin from ZIP File → Browse\nDownloads → EGPU-Buddy-Decky-0.7.242.zip", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source; installFromZip opens ZIP-only picker", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 26, "start": 499.72029166666664, "end": 517.8402916666666, "speechStart": 499.72029166666664, "speechEnd": 517.5602916666667}, {"duration": 17.24000000000001, "kind": "capture", "title": "4. Read Decky’s warning", "kicker": "EGPU BUDDY", "narration": "Decky shows a third-party plugin warning after Browse and before its file picker opens. Read it and check that the download came from the official project. Continue after any countdown, then select the ZIP. The URL route shows the same warning before starting its install flow.", "note": "Browse → third-party warning → Continue → file picker", "media": "decky-warning.png", "reference": "Actual upstream WarnThirdParty source-rendered sandbox; seconds=0 in capture", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 27, "start": 517.8402916666666, "end": 535.0802916666667, "speechStart": 517.8402916666666, "speechEnd": 534.8002916666667}, {"duration": 13.480000000000018, "kind": "capture", "title": "The download is in Downloads", "kicker": "EGPU BUDDY", "narration": "Select the Decky ZIP you downloaded, then confirm the selection. On a device with a different account name or browser download directory, use that location. Keep the ZIP intact; Decky reads it directly.", "note": "Select the ZIP file. Do not extract it.", "media": "file-picker.png", "reference": "Reconstructed picker screenshot; path/ZIP filtering verified in Decky DeveloperSettings source", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 28, "start": 535.0802916666667, "end": 548.5602916666667, "speechStart": 535.0802916666667, "speechEnd": 548.2802916666667}, {"duration": 12.919999999999959, "kind": "capture", "title": "Confirm EGPU Buddy, then open it", "kicker": "EGPU BUDDY", "narration": "Check the plugin name and version in the installation confirmation, and install it. Once Decky finishes, return to its plugin list and open EGPU Buddy. You have installed the plugin; the system integration comes next.", "note": "Confirm plugin name and version → Install → open EGPU Buddy", "media": "plugin-confirmation.png", "reference": "Reconstructed confirmation screenshot, exact PluginInstallModal locale wording", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 29, "start": 548.5602916666667, "end": 561.4802916666666, "speechStart": 548.5602916666667, "speechEnd": 561.2002916666667}, {"duration": 13.639999999999986, "kind": "capture", "title": "Alternative: paste the direct ZIP URL", "kicker": "EGPU BUDDY", "narration": "If you already have the direct release-asset link, paste it into Install Plugin from URL and choose Install. Use the ZIP download link, rather than the release-page address. This is an alternative to browsing for the downloaded file.", "note": "Alternative path only: direct ZIP asset URL → Install", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 30, "start": 561.4802916666666, "end": 575.1202916666666, "speechStart": 561.4802916666666, "speechEnd": 574.8402916666666}, {"duration": 18.279999999999973, "kind": "capture", "title": "5. Choose the external GPU vendor", "kicker": "EGPU BUDDY", "narration": "Press Install system integration. The next prompt asks Which GPU type will you use? Choose NVIDIA for an NVIDIA eGPU, or AMD / Intel beta for those external cards. Choose the eGPU’s vendor, even when your handheld’s built-in graphics uses another vendor.", "note": "Install system integration → external GPU vendor", "media": "install-choice.png", "reference": "Current actual plugin installClick rendered in sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 31, "start": 575.1202916666666, "end": 593.4002916666666, "speechStart": 575.1202916666666, "speechEnd": 593.1202916666666}, {"duration": 16.920041666666634, "kind": "capture", "title": "NVIDIA branch: build the patched driver", "kicker": "EGPU BUDDY", "narration": "For NVIDIA, the next confirmation is titled Install for an NVIDIA eGPU. Review the components and expected time, then continue. It installs the patched driver, the NVIDIA picture fix and the rest of the integration. Keep the charger connected and the eGPU unplugged.", "note": "NVIDIA → Install for an NVIDIA eGPU → Continue", "media": "install-confirm-nv.png", "reference": "Current confirmInstallNow with mocked NVIDIA install choice", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 32, "start": 593.4002916666666, "end": 610.3203333333332, "speechStart": 593.4002916666666, "speechEnd": 610.0403333333333}, {"duration": 24.75999999999999, "kind": "capture", "title": "AMD / Intel branch: no NVIDIA build", "kicker": "EGPU BUDDY", "narration": "For AMD or Intel, select AMD / Intel beta. The confirmation is titled Install for an AMD / Intel eGPU. The installer skips the patched NVIDIA driver and NVIDIA-only gamescope build, and installs the vendor-neutral attach, detach, fallback and audio integration. The shared confirmation still mentions NVIDIA components, but the AMD / Intel installer skips them. This path remains beta.", "note": "AMD / Intel (beta) → confirm → vendor-neutral integration\nSkips NVIDIA driver and NVIDIA-only gamescope build.", "media": "install-confirm-amd.png", "reference": "Actual prompt; install.sh GPU_VENDOR=amd gating; shared WHAT wording includes NVIDIA items even here", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 33, "start": 610.3203333333332, "end": 635.0803333333332, "speechStart": 610.3203333333332, "speechEnd": 634.8003333333332}, {"duration": 19.159999999999968, "kind": "capture", "title": "Conditional prompts: stop and read", "kicker": "EGPU BUDDY", "narration": "Your setup can add prompts. Unknown hardware can require I accept the risk. Conflicting eGPU tools can offer removal or cancellation. If Bazzite carries a built-in NVIDIA driver, use the appropriate non-NVIDIA handheld image before installing. Do not treat Continue anyway as a recommendation to ignore an incompatible image.", "note": "Conditional: untested hardware, conflicting tools, or NVIDIA image", "media": "install-untested.png", "reference": "Actual withConflictCheck / confirmInstallNow; Bazzite preflight", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 34, "start": 635.0803333333332, "end": 654.2403333333332, "speechStart": 635.0803333333332, "speechEnd": 653.9603333333332}, {"duration": 17.24000000000001, "kind": "capture", "title": "Conflicts need attention first", "kicker": "INSTALLATION • CONDITIONAL", "narration": "If a conflict prompt appears, read its identified tool or image and the evidence. Use the supported removal or image-change route. The screenshot shows the actual source-driven warning with a simulated Bazzite image conflict. Cancel rather than blindly continuing past an incompatible image.", "note": "Conflicts: read evidence and resolve before continuing.", "media": "install-conflict.png", "reference": "withConflictCheck; simulated Bazzite NVIDIA image state", "id": 35, "start": 654.2403333333332, "end": 671.4803333333332, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 654.2403333333332, "speechEnd": 671.2003333333332}, {"duration": 15.720000000000027, "kind": "capture", "title": "6. Wait for integration to finish", "kicker": "EGPU BUDDY", "narration": "The NVIDIA path can take several minutes while the driver builds. The AMD / Intel path skips that build. Read the actual progress and result rather than using the animation’s elapsed time. You can close the menu while work continues, and the plugin reports completion.", "note": "NVIDIA: patched driver build\nAMD / Intel: no NVIDIA build", "media": "install-progress-nv.png", "reference": "Actual Progress component with mocked progress; no installation executed", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 36, "start": 671.4803333333332, "end": 687.2003333333332, "speechStart": 671.4803333333332, "speechEnd": 686.9203333333332}, {"duration": 12.919999999999959, "kind": "capture", "title": "The AMD / Intel progress path", "kicker": "EGPU BUDDY", "narration": "Here is the same progress interface on the AMD / Intel branch. The capture uses a mocked installation step, so it demonstrates the layout rather than a successful hardware test. Follow the result on your own device.", "note": "AMD / Intel example • simulated progress, not a device test", "media": "install-progress-amd.png", "reference": "Current actual plugin with mocked AMD setup state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 37, "start": 687.2003333333332, "end": 700.1203333333332, "speechStart": 687.2003333333332, "speechEnd": 699.8403333333332}, {"duration": 14.279999999999973, "kind": "capture", "title": "If installation fails, repair first", "kicker": "INSTALLATION • ERROR PATH", "narration": "An installation error is not the success screen. Keep the eGPU unplugged, read the message and log location, and use the displayed Repair route. Resume the reboot and first-connect steps only after the integration reports success.", "note": "Error → keep eGPU unplugged → Repair / inspect log", "media": "install-error.png", "reference": "Current su.rc error path rendered with mocked rc20", "id": 38, "start": 700.1203333333332, "end": 714.4003333333332, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 700.1203333333332, "speechEnd": 714.1203333333332}, {"duration": 16.840000000000032, "kind": "capture", "title": "7. Reboot before connecting the eGPU", "kicker": "EGPU BUDDY", "narration": "When installation reports success, choose Reboot the system. Keep the eGPU unplugged throughout that reboot. The required kernel protections are not active until then. If an error appears, leave the eGPU unplugged and follow Repair or the displayed message before proceeding.", "note": "Success → Reboot the system\neGPU stays unplugged through reboot.", "media": "install-success.png", "reference": "Actual su.rc=0 / needs_reboot UI; mocked success state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 39, "start": 714.4003333333332, "end": 731.2403333333332, "speechStart": 714.4003333333332, "speechEnd": 730.9603333333331}, {"id": 40, "start": 731.2403333333332, "end": 747.2803333333331, "kind": "finish", "title": "Connect after the reboot", "kicker": "STEP 7 OF 7", "narration": "Once Game Mode is back, connect the eGPU and check its status in EGPU Buddy. Your setup is ready for its first test. You’ll find the downloads, tested hardware list and full instructions on GitHub, with the Discord link below. See you on the big screen.", "action": "Reconnect topology, then GitHub and Discord end card. User footage can reprise behind final labels.", "reference": "README.md Install / Reporting problems; Original §13", "duration": 16.039999999999964, "note": "After reboot: connect, inspect status, then test your setup.", "speechStart": 731.2403333333332, "speechEnd": 747.0003333333332}], "audio": "natural-voice.mp3?v=delivery-05", "script": "script-natural.txt"}, "helmet": {"label": "Helmet voice daft presentation", "duration": 1011.95425, "scenes": [{"id": 0, "start": 0, "end": 20, "kind": "footage", "title": "Real setup demonstration", "kicker": "OPENING • YOUR FOOTAGE", "narration": "Opening footage: actual eGPU connection, external Game Mode, unplug test and return to the handheld. The two waits are visibly accelerated. The opening video plays before the timed narration and can be skipped.", "action": "Reserved footage only. Keep the actual wait visible or mark an edit. Match-cut the handheld silhouette into the app glyph at 00:20. No recreated footage.", "reference": "VID20261109121330.mp4; source/intro-edit-plan.json", "duration": 20, "note": "Actual owner footage • 8x / 10x wait sections labeled"}, {"id": 1, "start": 20, "end": 39.84425, "kind": "hero", "title": "EGPU Buddy", "kicker": "GAME MODE. BIG SCREEN.", "narration": "This is EGPU Buddy. It brings an external graphics card into your Linux handheld’s Game Mode, with the controls right in the Quick Access menu. Your handheld has been promoted to command the big screen.", "action": "Handheld glyph glides in. Connection draws toward external display. Wordmark settles on the beat.", "reference": "README.md:11–17; plugin handhelds/lenovo-legion-go-2.svg", "duration": 19.84425, "note": "USB4 handheld → powered external GPU → monitor or TV", "speechStart": 25.839333333333332, "speechEnd": 39.56425}, {"duration": 33.590125, "kind": "requirements", "title": "The handheld needs USB4", "kicker": "EGPU BUDDY", "narration": "For a USB-connected eGPU, the handheld needs USB4 with PCIe tunneling, or a compatible Thunderbolt port. An ordinary USB-C charging or display port is not enough. Check the handheld, dock and cable. Older proprietary XG Mobile connectors use their own supported path. The tested XG Mobile 2025 uses the USB4 / Thunderbolt route. The connector may look innocent. The bandwidth must be worthy of the fleet.", "note": "USB-C describes the connector. USB4 / PCIe tunneling supplies the eGPU connection.", "media": null, "reference": "egpu-detect dock classification; TESTED.md XG Mobile 2025; USB4 PCIe requirement", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 2, "start": 39.84425, "end": 73.434375, "speechStart": 39.84425, "speechEnd": 73.154375}, {"duration": 26.227999999999994, "kind": "patches", "title": "What had to be fixed", "kicker": "EGPU BUDDY", "narration": "This took more than adding a menu. The NVIDIA driver needs changes so removal does not keep touching hardware that has gone away. Gamescope needs a different scan-out buffer path to fix NVIDIA picture corruption. The app also coordinates Game Mode, screens and audio, with system integration that survives OS updates. Performance supremacy requires engineering. A dramatic cape alone will not suffice.", "note": "Patched NVIDIA driver • gamescope scan-out fix • session and audio recovery", "media": null, "reference": "CREDITS.md hot-unplug driver and Game Mode corruption; packaging patches 160,165–167,170", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 3, "start": 73.434375, "end": 99.662375, "speechStart": 73.434375, "speechEnd": 99.382375}, {"duration": 28.796958333333322, "kind": "community", "title": "Built on community fixes", "kicker": "EGPU BUDDY", "narration": "The NVIDIA picture work builds on NightHammer1000 and antheas, with the root cause identified by matt-schwartz. The hot-unplug driver work builds on NickNill, bdandy and roger-pmta, plus this project’s removal cleanup patches. Decky supplies the plugin framework. These credits are part of the story, not just the closing card.", "note": "Picture: NightHammer1000 / antheas / matt-schwartz\nDriver: NickNill / bdandy / roger-pmta", "media": null, "reference": "CREDITS.md; upstream NVIDIA PRs #985 and #984", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 4, "start": 99.662375, "end": 128.45933333333332, "speechStart": 105.50170833333333, "speechEnd": 128.17933333333332}, {"id": 5, "start": 128.45933333333332, "end": 147.24391666666665, "kind": "parts", "title": "Three parts working together", "kicker": "UNDER THE SURFACE", "narration": "There are three parts: a Decky plugin for Game Mode, a desktop app with a tray icon, and the system integration underneath. That last part handles the driver and session setup, so the plugin can control it. Three stations. One slightly overdramatic command centre.", "action": "Three layers build vertically. Use real Decky icon, EGPU icon and source screenshot. Connection particles pass between layers.", "reference": "README.md Features / Install; desktop-app/; plugin src/index.tsx", "duration": 18.78458333333333, "note": "", "speechStart": 128.45933333333332, "speechEnd": 146.96391666666665}, {"id": 6, "start": 147.24391666666665, "end": 193.51820833333332, "kind": "hardware", "title": "Start with tested setups", "kicker": "HARDWARE", "narration": "Testing includes Legion Go 2 with the AORUS RTX 5060 Ti AI Box, Legion Go 1 with an RTX 3080 and AOOSTAR AG03, and ROG Xbox Ally X with XG Mobile 2025. Legion Go S Z1 Extreme is also in testing, including Ming’s Radeon RX 9070 XT setup. The original presentation captured that setup while AMD removal work was still in progress; consult the current release notes for its status. These are reported test combinations, not a blanket compatibility list. This is the test fleet, not a promise to conquer every dock in the galaxy.", "action": "Actual app glyphs reveal left to right. Pair each with its tested dock and card. Hold final row so combinations are readable.", "reference": "README.md Tested hardware; TESTED.md", "duration": 46.27429166666667, "note": "Legion Go S Z1 Extreme added • AMD removal issue remains open", "speechStart": 147.24391666666665, "speechEnd": 193.23820833333332}, {"duration": 41.109416666666675, "kind": "dockgallery", "title": "eGPU docks tested so far", "kicker": "PROJECT TEST HARDWARE", "narration": "The dock list includes the AORUS RTX 5060 Ti AI Box, AOOSTAR AG03 and AG02, ASUS XG Mobile 2025, MINISFORUM DEG2, and a TREBLEET Thunderbolt 3 enclosure. There is also another Intel JHL7440-based Thunderbolt 3 enclosure whose brand and model are not documented. These are project test reports, including testing still in progress. The catalog photographs identify the dock families, not every tester’s exact unit or revision.", "note": "Manufacturer/catalog photos • exact revisions may differ. Testing includes work in progress.", "docks": [{"name": "AORUS RTX 5060 Ti AI BOX", "gpu": "RTX 5060 Ti", "photo": "dock-aorus-user.png", "status": "Tested", "evidence": "README.md / TESTED.md: Legion Go 1 and 2; Bazzite / CachyOS / SteamOS", "original_photo": "Aorus 5060ti ai box.png", "bounds": [402, 16, 420, 744]}, {"name": "AOOSTAR AG03", "gpu": "RTX 3080", "photo": "dock-ag03-cutout.png", "status": "Tested", "evidence": "TESTED.md: Legion Go 1 / SteamOS", "original_photo": "dock-ag03.jpg", "bounds": [126, 19, 1283, 1000]}, {"name": "ASUS XG Mobile 2025", "gpu": "RTX 5070 Ti Laptop GPU", "photo": "xg-mobile-cutout.png", "status": "Tested", "evidence": "TESTED.md: SilverplayerX / ROG Xbox Ally X", "original_photo": "xg-mobile.jpg", "bounds": [22, 103, 1185, 1093]}, {"name": "AOOSTAR AG02", "gpu": "Radeon RX 6800 XT", "photo": "dock-ag02-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: RetroMann / Legion Go 1", "original_photo": "dock-ag02.jpg", "bounds": [107, 59, 1322, 935]}, {"name": "MINISFORUM DEG2", "gpu": "Radeon RX 9070", "photo": "dock-deg2-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: zergpoop / Legion Go 1", "original_photo": "dock-deg2.png", "bounds": [42, 132, 1697, 628]}, {"name": "TREBLEET Thunderbolt 3", "gpu": "Radeon RX 9070 XT", "photo": "dock-trebleet-cutout.png", "status": "Testing in progress", "evidence": "ACTIVE_TASK.md 2026-11-07/08: Ming / Legion Go S Z1E; exact product SKU not recorded; representative brand catalog photo", "original_photo": "dock-trebleet.jpg", "bounds": [48, 50, 1438, 934]}, {"name": "Other JHL7440 TB3 enclosure", "gpu": "Radeon RX 6750 XT", "photo": null, "status": "Model not documented", "evidence": "TESTED.md: Ivan C.nunes / Legion Go 1; Intel JHL7440 identifies controller, not brand/SKU"}], "reference": "README.md Tested hardware; TESTED.md; ACTIVE_TASK.md Ming 2026-11-07/08; asset-sources.json", "action": "Reveal the seven dock entries in a four-column gallery. Keep the unidentified enclosure explicitly unpictured.", "id": 7, "start": 193.51820833333332, "end": 234.627625, "speechStart": 199.35754166666666, "speechEnd": 234.347625}, {"duration": 45.47091666666668, "kind": "gpulist", "title": "GPUs tested and reported", "kicker": "PROJECT TEST HARDWARE", "narration": "The NVIDIA list is RTX 3080, RTX 5060 Ti, and the RTX 5070 Ti Laptop GPU inside XG Mobile 2025. An RTX 4070 has also been reported working by a user, with less complete setup detail. AMD testing includes Radeon RX 6800 XT, RX 6750 XT, RX 9070 and RX 9070 XT. AMD remains beta. No specific Intel eGPU model is documented as tested in this source set. An impressive gathering of graphics power. The electricity bill has requested diplomatic immunity.", "note": "Test reports are not a promise for every dock / OS combination.", "reference": "README.md NVIDIA generation paragraph and hardware table; TESTED.md AMD sections; ACTIVE_TASK.md Ming", "action": "Show NVIDIA and AMD lists together; distinguish user-reported RTX 4070 from detailed on-device testing.", "id": 8, "start": 234.627625, "end": 280.0985416666667, "speechStart": 234.627625, "speechEnd": 279.81854166666665}, {"duration": 21.963041666666697, "kind": "glyphcredit", "title": "Device glyphs by Victor Borges", "kicker": "EGPU BUDDY", "narration": "The device-specific handheld outlines come from Victor Borges’s handheld-controller-glyphs project. EGPU Buddy uses those real outlines in its screen picker. Thanks, Victor, for making them available under the MIT license.", "note": "Victor Borges / @victor-borges\ngithub.com/victor-borges/handheld-controller-glyphs", "media": null, "reference": "CREDITS.md handheld outlines; vendored LICENSE; github.com/victor-borges/handheld-controller-glyphs", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 9, "start": 280.0985416666667, "end": 302.0615833333334, "speechStart": 285.937875, "speechEnd": 301.78158333333334}, {"id": 10, "start": 302.0615833333334, "end": 322.1779583333334, "kind": "os", "title": "SteamOS. CachyOS. Bazzite.", "kicker": "LINUX GAME MODE", "narration": "The tested Game Mode systems are SteamOS, the handheld Deckify configuration of CachyOS, and Bazzite’s handheld image, bazzite-deck. NVIDIA is the main supported path. AMD and Intel use a beta path. Check the exact card, dock, device and operating-system combination.", "action": "Official distro marks enter together. Steam logo labeled SteamOS, not a custom SteamOS logo. Beta qualifier stays visible.", "reference": "README.md:15, Tested hardware; TESTED.md AMD / Intel", "duration": 20.116375000000005, "note": "CachyOS: handheld / Deckify\nBazzite: handheld image / bazzite-deck", "speechStart": 302.0615833333334, "speechEnd": 321.89795833333335}, {"id": 11, "start": 322.1779583333334, "end": 344.3255833333334, "kind": "attach", "title": "Connect, then let Game Mode move", "kicker": "THE EVERYDAY FLOW", "narration": "After installation and the required reboot, plugging in the eGPU starts the attach flow. On supported tested setups, Game Mode moves to the external screen and sound follows. The display can go dark briefly during the transition. The timing depends on the device and setup. The big screen awaits your arrival, commander.", "action": "Signal travels from handheld through eGPU. External display illuminates. Small transition label acknowledges brief black screen.", "reference": "README.md Features; original §6; current tested-path qualification", "duration": 22.147625000000005, "note": "A short dark-screen transition can be part of the attach flow.", "speechStart": 322.1779583333334, "speechEnd": 344.04558333333335}, {"id": 12, "start": 344.3255833333334, "end": 373.28645833333337, "kind": "detach", "title": "Safe Detach comes before unplugging", "kicker": "RETURN TO HANDHELD", "narration": "For a planned disconnect, close the game, open EGPU Buddy and choose Safe Detach. Confirm, keep the cable connected, and wait for Game Mode to return to the handheld. Reopen the menu and check that it says it is safe to unplug. That is the normal controlled route. Even a galactic overlord must respect the disconnect procedure.", "action": "Show real main screenshot beside step sequence. Signal fades toward handheld. Cable remains connected until confirmation. No yank demonstration.", "reference": "src/index.tsx Safe Detach confirmation and gameUp guard; ACTIVE_TASK supplied 2026-11-08 AMD detach issue", "duration": 28.960874999999987, "note": "Close game → Safe Detach → wait → read unplug status → unplug", "speechStart": 350.1649166666667, "speechEnd": 373.0064583333334}, {"duration": 27.57591666666667, "kind": "recovery", "title": "What if the cable gets pulled?", "kicker": "EGPU BUDDY", "narration": "The patched NVIDIA driver also handles surprise removal. It tracks that the GPU is gone and avoids invalid hardware accesses, while the app brings Game Mode back to the handheld. On tested NVIDIA setups, a yank recovers to a usable handheld in a way similar to Safe Detach, and replugging attaches again. A running game may close. This is recovery support, not a universal guarantee across all cards and docks.", "note": "Patched NVIDIA removal handling + app/session fallback\nTested recovery reaches the handheld again; a running game may close.", "media": null, "reference": "TESTED.md surprise removal table; CREDITS patches160/165–167/170; bdandy NVIDIA PR985", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 13, "start": 373.28645833333337, "end": 400.86237500000004, "speechStart": 373.28645833333337, "speechEnd": 400.582375}, {"id": 14, "start": 400.86237500000004, "end": 436.30304166666673, "kind": "screens", "title": "Choose where Game Mode appears", "kicker": "YOUR SCREENS", "narration": "The screen picker shows connected displays with their names, ports, resolution and refresh rate. The shapes distinguish a handheld, a TV and an ultrawide. Choose a screen to move Game Mode there. The default best-picture setting asks for native resolution and the highest refresh rate. Compatible screens can also wake and switch input automatically. Your pixels require more territory. Choose their next destination.", "action": "Main-page screenshot held large, with a traveling highlight. Device glyph fans into handheld and display choices.", "reference": "README.md Multiple displays / Best picture; src/index.tsx screenIcon / applyBestScreenModes", "duration": 35.44066666666669, "note": "", "speechStart": 406.7017083333334, "speechEnd": 436.0230416666667}, {"id": 15, "start": 436.30304166666673, "end": 450.9219583333334, "kind": "copyback", "title": "The eGPU can render for a small screen", "kicker": "HANDHELD AND XR", "narration": "You can keep the handheld screen while games render on the eGPU. XR glasses connected to the handheld can use the passthrough path too. Compatibility is still being tested, so check the current notes for your glasses and setup.", "action": "Reverse signal route from eGPU to handheld display. XR connection shown as a labeled output, not a universal support badge.", "reference": "src/index.tsx XR connected dialog; supplied ACTIVE_TASK pending AR retest", "duration": 14.618916666666678, "note": "", "speechStart": 436.30304166666673, "speechEnd": 450.6419583333334}, {"id": 16, "start": 450.9219583333334, "end": 473.88654166666674, "kind": "telemetry", "title": "Readings and GPU controls", "kicker": "DETAILS", "narration": "Details shows the GPU, driver, connection and live readings: temperature, power, clocks, memory and load. Available controls include a power limit and clock offset. What you can change depends on the card and install path. The animated example values are illustrations; check the real readings on your device. Study the telemetry before declaring thermal supremacy.", "action": "Real Details screenshot moves upward slowly. Telemetry labels animate beside it; no invented FPS or benchmark numbers.", "reference": "README.md GPU details; plugin Details; original §8", "duration": 22.964583333333337, "note": "", "speechStart": 450.9219583333334, "speechEnd": 473.6065416666667}, {"id": 17, "start": 473.88654166666674, "end": 501.0733750000001, "kind": "xg", "title": "XG Mobile gets its own controls", "kicker": "ASUS DOCK", "narration": "On the supported ASUS XG Mobile setup, the plugin and desktop app expose the power target, fan modes, a custom fan curve, dock lighting, and core and memory offsets. These are specific dock controls, shown here with the project’s real interface. Control the lights, command the fans, and resist the temptation to call it a space station.", "action": "Official ASUS product photo paired with real XG screenshot. Gentle push in, then fan/light/power labels appear.", "reference": "README.md ASUS XG Mobile; screenshot-xg-mobile.png; ASUS gallery", "duration": 27.186833333333368, "note": "", "speechStart": 479.7258750000001, "speechEnd": 500.7933750000001}, {"id": 18, "start": 501.0733750000001, "end": 521.8997083333334, "kind": "desktop", "title": "The same setup on the desktop", "kicker": "DESKTOP APP", "narration": "Desktop Mode has an EGPU Buddy app and tray icon, with GPU readings, screen selection, power controls, Safe Detach and Re-attach. This screenshot uses an ASUS XG Mobile: the lighting and fan controls shown here are specific to that dock. The command centre is now open for desktop business.", "action": "Actual desktop screenshot fills right side. App icon moves down toward an illustrated tray position, labeled schematic.", "reference": "README.md Desktop app / Multiple displays; desktop screenshot", "duration": 20.82633333333331, "note": "Desktop app / tray access\nLighting and fan controls shown: ASUS XG Mobile only", "speechStart": 501.0733750000001, "speechEnd": 521.6197083333334}, {"id": 19, "start": 521.8997083333334, "end": 551.8585, "kind": "experimental", "title": "Optional settings (experimental)", "kicker": "TRY WITH CARE", "narration": "NVIDIA settings adds low latency, V-sync and frame limits. AMD’s Adrenaline Settings adds supported Linux equivalents, with experimental FSR upgrades and Fluid Motion Frames for compatible games. Other opt-in extras include USB4 link checks and LG TV control. The Big Art mode menu fix is for NVIDIA only. Experimental means experimental. The laws of physics have declined our request for absolute dominance.", "action": "Three labeled text lanes appear. Experimental label stays on screen. Avoid Windows vendor control-panel screenshots.", "reference": "RELEASE-NOTES.md 0.7.236; README.md NV GPU Buddy; src/index.tsx", "duration": 29.958791666666627, "note": "", "speechStart": 521.8997083333334, "speechEnd": 551.5785000000001}, {"id": 20, "start": 551.8585, "end": 586.5818750000001, "kind": "report", "title": "Save a report for Discord support", "kicker": "DISCORD SUPPORT", "narration": "For help on Discord, open EGPU Buddy and choose Show details. Under Support report, select Save support report to Desktop. Wait for it to finish. Then switch to Desktop Mode and open your Desktop folder. In the Discord support channel, attach the saved report file with a short description of the problem and what you were doing when it happened. Send the report. Our support fleet cannot diagnose a disturbance in the graphics by telepathy.", "action": "Highlight the source-rendered Save support report to Desktop button; show the saved file moving from Desktop to a Discord attachment step. Demo file only.", "reference": "capture-sandbox/plugin-source.tsx Support report section, makeReport; user requested Discord support workflow", "duration": 34.72337500000003, "note": "Show details → Support report → Save to Desktop → attach the file in Discord", "speechStart": 557.6978333333334, "speechEnd": 586.3018750000001}, {"id": 21, "start": 586.5818750000001, "end": 612.8967500000001, "kind": "credits", "title": "Built with testers and upstream projects", "kicker": "THANK YOU", "narration": "Thanks to the hardware testers, including SilverplayerX, 1khanfusion, RetroMann, Ivan C.nunes, zergpoop, akamel001 and Ming. Thanks also to Victor Borges for the handheld glyphs, and the projects and patch authors credited earlier. The full list is in CREDITS.md. Next, let’s install the plugin. No single commander built this fleet alone.", "action": "Tester names hold in two columns. Short upstream line, then chapter wipe into how-to. Full attribution in source files.", "reference": "CREDITS.md; original §12", "duration": 26.31487500000003, "note": "Hardware testers + patch authors + Victor Borges / handheld-controller-glyphs", "speechStart": 586.5818750000001, "speechEnd": 612.6167500000001}, {"id": 22, "start": 612.8967500000001, "end": 630.9603750000001, "kind": "tutorial", "title": "Install the Decky plugin", "kicker": "HOW TO • GAME MODE", "narration": "With Decky Loader already installed, we will add the EGPU Buddy plugin from Game Mode, then install its system integration. Those are two separate steps.", "action": "Chapter card with Decky icon and app icon. Two-stage graphic separates plugin from system integration.", "reference": "README.md Install; Decky official README", "duration": 18.063625000000002, "note": "Decky Loader already installed → EGPU Buddy plugin → system integration.", "speechStart": 618.7360833333335, "speechEnd": 630.6803750000001}, {"id": 23, "start": 630.9603750000001, "end": 649.1182916666668, "kind": "prereq", "title": "Before you start", "kicker": "STEP 1 OF 7", "narration": "This tutorial assumes Decky Loader is already installed. Start in Game Mode, with internet and power available. Keep the eGPU unplugged during installation and the reboot afterwards. A stable power supply is more useful than unlimited dramatic confidence.", "action": "Unplugged cable graphic. Official Decky-on-device image held beside prerequisite. On-screen installer URL decky.xyz.", "reference": "README.md Install; https://github.com/SteamDeckHomebrew/decky-loader#installation", "duration": 18.157916666666665, "media": "decky-general.png", "note": "Decky Loader already installed.\nKeep eGPU unplugged through installation AND reboot.", "speechStart": 630.9603750000001, "speechEnd": 648.8382916666668}, {"duration": 13.908874999999966, "kind": "capture", "title": "1. Enable Decky Developer mode", "kicker": "EGPU BUDDY", "narration": "In Game Mode, open the Quick Access menu and select Decky. Open Decky’s settings, choose General, and turn on Developer mode. The Developer tab becomes available. This is Decky’s setting, not Steam’s separate developer menu.", "note": "Quick Access → Decky → Settings → General\nDeveloper mode: ON", "media": "decky-general.png", "reference": "Actual upstream GeneralSettings component, source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 24, "start": 649.1182916666668, "end": 663.0271666666667, "speechStart": 649.1182916666668, "speechEnd": 662.7471666666668}, {"duration": 18.339124999999967, "kind": "capture", "title": "2. Download the Decky ZIP", "kicker": "EGPU BUDDY", "narration": "The file route avoids typing a long URL. Open the project’s Releases page in a browser. Desktop Mode is the simplest place to do that. Download the EGPU-Buddy-Decky ZIP asset for the current release. Do not choose the dot run desktop installer or GitHub’s source-code ZIP.", "note": "Browser download → EGPU-Buddy-Decky-<version>.zip\nDesktop Mode is simplest; return to Game Mode afterward.", "media": "github-release-actual.png", "reference": "Actual GitHub release page read-only capture; verified release v0.7.242", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 25, "start": 663.0271666666667, "end": 681.3662916666667, "speechStart": 663.0271666666667, "speechEnd": 681.0862916666667}, {"duration": 23.73866666666663, "kind": "capture", "title": "3. Browse to the downloaded ZIP", "kicker": "EGPU BUDDY", "narration": "Return to Game Mode. In Decky settings, open Developer. Under Install Plugin from ZIP File, choose Browse. In the file picker, open your Downloads folder and select the EGPU Buddy Decky ZIP. The file route and URL route install the same plugin.", "note": "Developer → Install Plugin from ZIP File → Browse\nDownloads → EGPU-Buddy-Decky-0.7.242.zip", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source; installFromZip opens ZIP-only picker", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 26, "start": 681.3662916666667, "end": 705.1049583333333, "speechStart": 687.205625, "speechEnd": 704.8249583333334}, {"duration": 16.393458333333342, "kind": "capture", "title": "4. Read Decky’s warning", "kicker": "EGPU BUDDY", "narration": "Decky shows a third-party plugin warning after Browse and before its file picker opens. Read it and check that the download came from the official project. Continue after any countdown, then select the ZIP. The URL route shows the same warning before starting its install flow.", "note": "Browse → third-party warning → Continue → file picker", "media": "decky-warning.png", "reference": "Actual upstream WarnThirdParty source-rendered sandbox; seconds=0 in capture", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 27, "start": 705.1049583333333, "end": 721.4984166666667, "speechStart": 705.1049583333333, "speechEnd": 721.2184166666667}, {"duration": 13.912291666666647, "kind": "capture", "title": "The download is in Downloads", "kicker": "EGPU BUDDY", "narration": "Select the Decky ZIP you downloaded, then confirm the selection. On a device with a different account name or browser download directory, use that location. Keep the ZIP intact; Decky reads it directly.", "note": "Select the ZIP file. Do not extract it.", "media": "file-picker.png", "reference": "Reconstructed picker screenshot; path/ZIP filtering verified in Decky DeveloperSettings source", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 28, "start": 721.4984166666667, "end": 735.4107083333333, "speechStart": 721.4984166666667, "speechEnd": 735.1307083333334}, {"duration": 16.033874999999966, "kind": "capture", "title": "Confirm EGPU Buddy, then open it", "kicker": "EGPU BUDDY", "narration": "Check the plugin name and version in the installation confirmation, and install it. Once Decky finishes, return to its plugin list and open EGPU Buddy. You have installed the plugin; the system integration comes next.", "note": "Confirm plugin name and version → Install → open EGPU Buddy", "media": "plugin-confirmation.png", "reference": "Reconstructed confirmation screenshot, exact PluginInstallModal locale wording", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 29, "start": 735.4107083333333, "end": 751.4445833333333, "speechStart": 735.4107083333333, "speechEnd": 751.1645833333333}, {"duration": 21.882458333333375, "kind": "capture", "title": "Alternative: paste the direct ZIP URL", "kicker": "EGPU BUDDY", "narration": "If you already have the direct release-asset link, paste it into Install Plugin from URL and choose Install. Use the ZIP download link, rather than the release-page address. This is an alternative to browsing for the downloaded file.", "note": "Alternative path only: direct ZIP asset URL → Install", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 30, "start": 751.4445833333333, "end": 773.3270416666667, "speechStart": 757.2839166666666, "speechEnd": 773.0470416666666}, {"duration": 21.798958333333303, "kind": "capture", "title": "5. Choose the external GPU vendor", "kicker": "EGPU BUDDY", "narration": "Press Install system integration. The next prompt asks Which GPU type will you use? Choose NVIDIA for an NVIDIA eGPU, or AMD / Intel beta for those external cards. Choose the eGPU’s vendor, even when your handheld’s built-in graphics uses another vendor.", "note": "Install system integration → external GPU vendor", "media": "install-choice.png", "reference": "Current actual plugin installClick rendered in sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 31, "start": 773.3270416666667, "end": 795.126, "speechStart": 773.3270416666667, "speechEnd": 794.846}, {"duration": 21.890583333333325, "kind": "capture", "title": "NVIDIA branch: build the patched driver", "kicker": "EGPU BUDDY", "narration": "For NVIDIA, the next confirmation is titled Install for an NVIDIA eGPU. Review the components and expected time, then continue. It installs the patched driver, the NVIDIA picture fix and the rest of the integration. Keep the charger connected and the eGPU unplugged. Patience, commander. The driver is being forged.", "note": "NVIDIA → Install for an NVIDIA eGPU → Continue", "media": "install-confirm-nv.png", "reference": "Current confirmInstallNow with mocked NVIDIA install choice", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 32, "start": 795.126, "end": 817.0165833333333, "speechStart": 795.126, "speechEnd": 816.7365833333333}, {"duration": 36.22895833333337, "kind": "capture", "title": "AMD / Intel branch: no NVIDIA build", "kicker": "EGPU BUDDY", "narration": "For AMD or Intel, select AMD / Intel beta. The confirmation is titled Install for an AMD / Intel eGPU. The installer skips the patched NVIDIA driver and NVIDIA-only gamescope build, and installs the vendor-neutral attach, detach, fallback and audio integration. The shared confirmation still mentions NVIDIA components, but the AMD / Intel installer skips them. This path remains beta.", "note": "AMD / Intel (beta) → confirm → vendor-neutral integration\nSkips NVIDIA driver and NVIDIA-only gamescope build.", "media": "install-confirm-amd.png", "reference": "Actual prompt; install.sh GPU_VENDOR=amd gating; shared WHAT wording includes NVIDIA items even here", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 33, "start": 817.0165833333333, "end": 853.2455416666667, "speechStart": 822.8559166666666, "speechEnd": 852.9655416666667}, {"duration": 24.81258333333335, "kind": "capture", "title": "Conditional prompts: stop and read", "kicker": "EGPU BUDDY", "narration": "Your setup can add prompts. Unknown hardware can require I accept the risk. Conflicting eGPU tools can offer removal or cancellation. If Bazzite carries a built-in NVIDIA driver, use the appropriate non-NVIDIA handheld image before installing. Do not treat Continue anyway as a recommendation to ignore an incompatible image.", "note": "Conditional: untested hardware, conflicting tools, or NVIDIA image", "media": "install-untested.png", "reference": "Actual withConflictCheck / confirmInstallNow; Bazzite preflight", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 34, "start": 853.2455416666667, "end": 878.058125, "speechStart": 853.2455416666667, "speechEnd": 877.778125}, {"duration": 27.820875, "kind": "capture", "title": "Conflicts need attention first", "kicker": "INSTALLATION • CONDITIONAL", "narration": "If a conflict prompt appears, read its identified tool or image and the evidence. Use the supported removal or image-change route. The screenshot shows the actual source-driven warning with a simulated Bazzite image conflict. Cancel rather than blindly continuing past an incompatible image.", "note": "Conflicts: read evidence and resolve before continuing.", "media": "install-conflict.png", "reference": "withConflictCheck; simulated Bazzite NVIDIA image state", "id": 35, "start": 878.058125, "end": 905.879, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 883.8974583333334, "speechEnd": 905.599}, {"duration": 21.709208333333322, "kind": "capture", "title": "6. Wait for integration to finish", "kicker": "EGPU BUDDY", "narration": "The NVIDIA path can take several minutes while the driver builds. The AMD / Intel path skips that build. Read the actual progress and result rather than using the animation’s elapsed time. You can close the menu while work continues, and the plugin reports completion. The progress bar will not move faster if you threaten the galaxy.", "note": "NVIDIA: patched driver build\nAMD / Intel: no NVIDIA build", "media": "install-progress-nv.png", "reference": "Actual Progress component with mocked progress; no installation executed", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 36, "start": 905.879, "end": 927.5882083333333, "speechStart": 905.879, "speechEnd": 927.3082083333334}, {"duration": 14.617875000000026, "kind": "capture", "title": "The AMD / Intel progress path", "kicker": "EGPU BUDDY", "narration": "Here is the same progress interface on the AMD / Intel branch. The capture uses a mocked installation step, so it demonstrates the layout rather than a successful hardware test. Follow the result on your own device.", "note": "AMD / Intel example • simulated progress, not a device test", "media": "install-progress-amd.png", "reference": "Current actual plugin with mocked AMD setup state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 37, "start": 927.5882083333333, "end": 942.2060833333334, "speechStart": 927.5882083333333, "speechEnd": 941.9260833333334}, {"duration": 21.786500000000046, "kind": "capture", "title": "If installation fails, repair first", "kicker": "INSTALLATION • ERROR PATH", "narration": "An installation error is not the success screen. Keep the eGPU unplugged, read the message and log location, and use the displayed Repair route. Resume the reboot and first-connect steps only after the integration reports success.", "note": "Error → keep eGPU unplugged → Repair / inspect log", "media": "install-error.png", "reference": "Current su.rc error path rendered with mocked rc20", "id": 38, "start": 942.2060833333334, "end": 963.9925833333334, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 948.0454166666667, "speechEnd": 963.7125833333333}, {"duration": 25.184041666666644, "kind": "capture", "title": "7. Reboot before connecting the eGPU", "kicker": "EGPU BUDDY", "narration": "When installation reports success, choose Reboot the system. Keep the eGPU unplugged throughout that reboot. The required kernel protections are not active until then. If an error appears, leave the eGPU unplugged and follow Repair or the displayed message before proceeding. One reboot now. Galactic ambitions afterwards.", "note": "Success → Reboot the system\neGPU stays unplugged through reboot.", "media": "install-success.png", "reference": "Actual su.rc=0 / needs_reboot UI; mocked success state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 39, "start": 963.9925833333334, "end": 989.1766250000001, "speechStart": 963.9925833333334, "speechEnd": 988.8966250000001}, {"id": 40, "start": 989.1766250000001, "end": 1011.95425, "kind": "finish", "title": "Connect after the reboot", "kicker": "STEP 7 OF 7", "narration": "Once Game Mode is back, connect the eGPU and check its status in EGPU Buddy. Your setup is ready for its first test. You’ll find the downloads, tested hardware list and full instructions on GitHub, with the Discord link below. See you on the big screen. May your frame times be steady, your thermals controlled, and your desktop space magnificently excessive.", "action": "Reconnect topology, then GitHub and Discord end card. User footage can reprise behind final labels.", "reference": "README.md Install / Reporting problems; Original §13", "duration": 22.777624999999944, "note": "After reboot: connect, inspect status, then test your setup.", "speechStart": 989.1766250000001, "speechEnd": 1011.67425}], "audio": "helmet-voice.mp3?v=helmet-v2-07", "script": "script-helmet.txt", "playbackRate": 1, "speechTempo": 0.9025, "breathNativeSeconds": 5.589333333333333}, "radio": {"label": "Radio host daft presentation", "duration": 810.5600000000002, "scenes": [{"id": 0, "start": 0, "end": 20, "kind": "footage", "title": "Real setup demonstration", "kicker": "OPENING • YOUR FOOTAGE", "narration": "Opening footage: actual eGPU connection, external Game Mode, unplug test and return to the handheld. The two waits are visibly accelerated. The opening video plays before the timed narration and can be skipped.", "action": "Reserved footage only. Keep the actual wait visible or mark an edit. Match-cut the handheld silhouette into the app glyph at 00:20. No recreated footage.", "reference": "VID20261109121330.mp4; source/intro-edit-plan.json", "duration": 20, "note": "Actual owner footage • 8x / 10x wait sections labeled"}, {"id": 1, "start": 20, "end": 33.32, "kind": "hero", "title": "EGPU Buddy", "kicker": "GAME MODE. BIG SCREEN.", "narration": "You're tuned to the big-screen frequency. This is EGPU Buddy. It brings an external graphics card into your Linux handheld’s Game Mode, with the controls right in the Quick Access menu.", "action": "Handheld glyph glides in. Connection draws toward external display. Wordmark settles on the beat.", "reference": "README.md:11–17; plugin handhelds/lenovo-legion-go-2.svg", "duration": 13.319999999999999, "note": "USB4 handheld → powered external GPU → monitor or TV", "speechStart": 20, "speechEnd": 33.04}, {"duration": 26.519999999999996, "kind": "requirements", "title": "The handheld needs USB4", "kicker": "EGPU BUDDY", "narration": "For a USB-connected eGPU, the handheld needs USB4 with PCIe tunneling, or a compatible Thunderbolt port. An ordinary USB-C charging or display port is not enough. Check the handheld, dock and cable. Older proprietary XG Mobile connectors use their own supported path. The tested XG Mobile 2025 uses the USB4 / Thunderbolt route. USB-C is a shape, not a magic spell.", "note": "USB-C describes the connector. USB4 / PCIe tunneling supplies the eGPU connection.", "media": null, "reference": "egpu-detect dock classification; TESTED.md XG Mobile 2025; USB4 PCIe requirement", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 2, "start": 33.32, "end": 59.839999999999996, "speechStart": 33.32, "speechEnd": 59.56}, {"duration": 25.720000000000006, "kind": "patches", "title": "What had to be fixed", "kicker": "EGPU BUDDY", "narration": "This took more than adding a menu. The NVIDIA driver needs changes so removal does not keep touching hardware that has gone away. Gamescope needs a different scan-out buffer path to fix NVIDIA picture corruption. The app also coordinates Game Mode, screens and audio, with system integration that survives OS updates. Several stubborn gremlins were politely asked to leave. They declined. Patches followed.", "note": "Patched NVIDIA driver • gamescope scan-out fix • session and audio recovery", "media": null, "reference": "CREDITS.md hot-unplug driver and Game Mode corruption; packaging patches 160,165–167,170", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 3, "start": 59.839999999999996, "end": 85.56, "speechStart": 59.839999999999996, "speechEnd": 85.28}, {"duration": 20.92, "kind": "community", "title": "Built on community fixes", "kicker": "EGPU BUDDY", "narration": "The NVIDIA picture work builds on NightHammer1000 and antheas, with the root cause identified by matt-schwartz. The hot-unplug driver work builds on NickNill, bdandy and roger-pmta, plus this project’s removal cleanup patches. Decky supplies the plugin framework. These credits are part of the story, not just the closing card.", "note": "Picture: NightHammer1000 / antheas / matt-schwartz\nDriver: NickNill / bdandy / roger-pmta", "media": null, "reference": "CREDITS.md; upstream NVIDIA PRs #985 and #984", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 4, "start": 85.56, "end": 106.48, "speechStart": 85.56, "speechEnd": 106.2}, {"id": 5, "start": 106.48, "end": 119.56, "kind": "parts", "title": "Three parts working together", "kicker": "UNDER THE SURFACE", "narration": "There are three parts: a Decky plugin for Game Mode, a desktop app with a tray icon, and the system integration underneath. That last part handles the driver and session setup, so the plugin can control it.", "action": "Three layers build vertically. Use real Decky icon, EGPU icon and source screenshot. Connection particles pass between layers.", "reference": "README.md Features / Install; desktop-app/; plugin src/index.tsx", "duration": 13.079999999999998, "note": "", "speechStart": 106.48, "speechEnd": 119.28}, {"id": 6, "start": 119.56, "end": 152.96, "kind": "hardware", "title": "Start with tested setups", "kicker": "HARDWARE", "narration": "Testing includes Legion Go 2 with the AORUS RTX 5060 Ti AI Box, Legion Go 1 with an RTX 3080 and AOOSTAR AG03, and ROG Xbox Ally X with XG Mobile 2025. Legion Go S Z1 Extreme is also in testing, including Ming’s Radeon RX 9070 XT setup. The original presentation captured that setup while AMD removal work was still in progress; consult the current release notes for its status. These are reported test combinations, not a blanket compatibility list. The test bench is busy. The crystal ball remains unplugged.", "action": "Actual app glyphs reveal left to right. Pair each with its tested dock and card. Hold final row so combinations are readable.", "reference": "README.md Tested hardware; TESTED.md", "duration": 33.400000000000006, "note": "Legion Go S Z1 Extreme added • AMD removal issue remains open", "speechStart": 119.56, "speechEnd": 152.68}, {"duration": 35.0, "kind": "dockgallery", "title": "eGPU docks tested so far", "kicker": "PROJECT TEST HARDWARE", "narration": "The dock list includes the AORUS RTX 5060 Ti AI Box, AOOSTAR AG03 and AG02, ASUS XG Mobile 2025, MINISFORUM DEG2, and a TREBLEET Thunderbolt 3 enclosure. There is also another Intel JHL7440-based Thunderbolt 3 enclosure whose brand and model are not documented. These are project test reports, including testing still in progress. The catalog photographs identify the dock families, not every tester’s exact unit or revision. A small gathering of boxes with a very expensive hobby.", "note": "Manufacturer/catalog photos • exact revisions may differ. Testing includes work in progress.", "docks": [{"name": "AORUS RTX 5060 Ti AI BOX", "gpu": "RTX 5060 Ti", "photo": "dock-aorus-user.png", "status": "Tested", "evidence": "README.md / TESTED.md: Legion Go 1 and 2; Bazzite / CachyOS / SteamOS", "original_photo": "Aorus 5060ti ai box.png", "bounds": [402, 16, 420, 744]}, {"name": "AOOSTAR AG03", "gpu": "RTX 3080", "photo": "dock-ag03-cutout.png", "status": "Tested", "evidence": "TESTED.md: Legion Go 1 / SteamOS", "original_photo": "dock-ag03.jpg", "bounds": [126, 19, 1283, 1000]}, {"name": "ASUS XG Mobile 2025", "gpu": "RTX 5070 Ti Laptop GPU", "photo": "xg-mobile-cutout.png", "status": "Tested", "evidence": "TESTED.md: SilverplayerX / ROG Xbox Ally X", "original_photo": "xg-mobile.jpg", "bounds": [22, 103, 1185, 1093]}, {"name": "AOOSTAR AG02", "gpu": "Radeon RX 6800 XT", "photo": "dock-ag02-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: RetroMann / Legion Go 1", "original_photo": "dock-ag02.jpg", "bounds": [107, 59, 1322, 935]}, {"name": "MINISFORUM DEG2", "gpu": "Radeon RX 9070", "photo": "dock-deg2-cutout.png", "status": "Testing in progress", "evidence": "TESTED.md: zergpoop / Legion Go 1", "original_photo": "dock-deg2.png", "bounds": [42, 132, 1697, 628]}, {"name": "TREBLEET Thunderbolt 3", "gpu": "Radeon RX 9070 XT", "photo": "dock-trebleet-cutout.png", "status": "Testing in progress", "evidence": "ACTIVE_TASK.md 2026-11-07/08: Ming / Legion Go S Z1E; exact product SKU not recorded; representative brand catalog photo", "original_photo": "dock-trebleet.jpg", "bounds": [48, 50, 1438, 934]}, {"name": "Other JHL7440 TB3 enclosure", "gpu": "Radeon RX 6750 XT", "photo": null, "status": "Model not documented", "evidence": "TESTED.md: Ivan C.nunes / Legion Go 1; Intel JHL7440 identifies controller, not brand/SKU"}], "reference": "README.md Tested hardware; TESTED.md; ACTIVE_TASK.md Ming 2026-11-07/08; asset-sources.json", "action": "Reveal the seven dock entries in a four-column gallery. Keep the unidentified enclosure explicitly unpictured.", "id": 7, "start": 152.96, "end": 187.96, "speechStart": 152.96, "speechEnd": 187.68}, {"duration": 35.879999999999995, "kind": "gpulist", "title": "GPUs tested and reported", "kicker": "PROJECT TEST HARDWARE", "narration": "The NVIDIA list is RTX 3080, RTX 5060 Ti, and the RTX 5070 Ti Laptop GPU inside XG Mobile 2025. An RTX 4070 has also been reported working by a user, with less complete setup detail. AMD testing includes Radeon RX 6800 XT, RX 6750 XT, RX 9070 and RX 9070 XT. AMD remains beta. No specific Intel eGPU model is documented as tested in this source set.", "note": "Test reports are not a promise for every dock / OS combination.", "reference": "README.md NVIDIA generation paragraph and hardware table; TESTED.md AMD sections; ACTIVE_TASK.md Ming", "action": "Show NVIDIA and AMD lists together; distinguish user-reported RTX 4070 from detailed on-device testing.", "id": 8, "start": 187.96, "end": 223.84, "speechStart": 187.96, "speechEnd": 223.56}, {"duration": 13.960000000000008, "kind": "glyphcredit", "title": "Device glyphs by Victor Borges", "kicker": "EGPU BUDDY", "narration": "The device-specific handheld outlines come from Victor Borges’s handheld-controller-glyphs project. EGPU Buddy uses those real outlines in its screen picker. Thanks, Victor, for making them available under the MIT license.", "note": "Victor Borges / @victor-borges\ngithub.com/victor-borges/handheld-controller-glyphs", "media": null, "reference": "CREDITS.md handheld outlines; vendored LICENSE; github.com/victor-borges/handheld-controller-glyphs", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 9, "start": 223.84, "end": 237.8, "speechStart": 223.84, "speechEnd": 237.52}, {"id": 10, "start": 237.8, "end": 255.60000000000002, "kind": "os", "title": "SteamOS. CachyOS. Bazzite.", "kicker": "LINUX GAME MODE", "narration": "The tested Game Mode systems are SteamOS, the handheld Deckify configuration of CachyOS, and Bazzite’s handheld image, bazzite-deck. NVIDIA is the main supported path. AMD and Intel use a beta path. Check the exact card, dock, device and operating-system combination.", "action": "Official distro marks enter together. Steam logo labeled SteamOS, not a custom SteamOS logo. Beta qualifier stays visible.", "reference": "README.md:15, Tested hardware; TESTED.md AMD / Intel", "duration": 17.80000000000001, "note": "CachyOS: handheld / Deckify\nBazzite: handheld image / bazzite-deck", "speechStart": 237.8, "speechEnd": 255.32000000000002}, {"id": 11, "start": 255.60000000000002, "end": 276.68, "kind": "attach", "title": "Connect, then let Game Mode move", "kicker": "THE EVERYDAY FLOW", "narration": "After installation and the required reboot, plugging in the eGPU starts the attach flow. On supported tested setups, Game Mode moves to the external screen and sound follows. The display can go dark briefly during the transition. The timing depends on the device and setup. Small handheld. Large entrance. Absolutely no red-carpet budget.", "action": "Signal travels from handheld through eGPU. External display illuminates. Small transition label acknowledges brief black screen.", "reference": "README.md Features; original §6; current tested-path qualification", "duration": 21.079999999999984, "note": "A short dark-screen transition can be part of the attach flow.", "speechStart": 255.60000000000002, "speechEnd": 276.40000000000003}, {"id": 12, "start": 276.68, "end": 294.48, "kind": "detach", "title": "Safe Detach comes before unplugging", "kicker": "RETURN TO HANDHELD", "narration": "For a planned disconnect, close the game, open EGPU Buddy and choose Safe Detach. Confirm, keep the cable connected, and wait for Game Mode to return to the handheld. Reopen the menu and check that it says it is safe to unplug. That is the normal controlled route. Think of it as saying goodbye before leaving the party.", "action": "Show real main screenshot beside step sequence. Signal fades toward handheld. Cable remains connected until confirmation. No yank demonstration.", "reference": "src/index.tsx Safe Detach confirmation and gameUp guard; ACTIVE_TASK supplied 2026-11-08 AMD detach issue", "duration": 17.80000000000001, "note": "Close game → Safe Detach → wait → read unplug status → unplug", "speechStart": 276.68, "speechEnd": 294.2}, {"duration": 26.279999999999973, "kind": "recovery", "title": "What if the cable gets pulled?", "kicker": "EGPU BUDDY", "narration": "The patched NVIDIA driver also handles surprise removal. It tracks that the GPU is gone and avoids invalid hardware accesses, while the app brings Game Mode back to the handheld. On tested NVIDIA setups, a yank recovers to a usable handheld in a way similar to Safe Detach, and replugging attaches again. A running game may close. This is recovery support, not a universal guarantee across all cards and docks.", "note": "Patched NVIDIA removal handling + app/session fallback\nTested recovery reaches the handheld again; a running game may close.", "media": null, "reference": "TESTED.md surprise removal table; CREDITS patches160/165–167/170; bdandy NVIDIA PR985", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 13, "start": 294.48, "end": 320.76, "speechStart": 294.48, "speechEnd": 320.48}, {"id": 14, "start": 320.76, "end": 341.76, "kind": "screens", "title": "Choose where Game Mode appears", "kicker": "YOUR SCREENS", "narration": "The screen picker shows connected displays with their names, ports, resolution and refresh rate. The shapes distinguish a handheld, a TV and an ultrawide. Choose a screen to move Game Mode there. The default best-picture setting asks for native resolution and the highest refresh rate. Compatible screens can also wake and switch input automatically.", "action": "Main-page screenshot held large, with a traveling highlight. Device glyph fans into handheld and display choices.", "reference": "README.md Multiple displays / Best picture; src/index.tsx screenIcon / applyBestScreenModes", "duration": 21.0, "note": "", "speechStart": 320.76, "speechEnd": 341.48}, {"id": 15, "start": 341.76, "end": 355.8, "kind": "copyback", "title": "The eGPU can render for a small screen", "kicker": "HANDHELD AND XR", "narration": "You can keep the handheld screen while games render on the eGPU. XR glasses connected to the handheld can use the passthrough path too. Compatibility is still being tested, so check the current notes for your glasses and setup.", "action": "Reverse signal route from eGPU to handheld display. XR connection shown as a labeled output, not a universal support badge.", "reference": "src/index.tsx XR connected dialog; supplied ACTIVE_TASK pending AR retest", "duration": 14.04000000000002, "note": "", "speechStart": 341.76, "speechEnd": 355.52}, {"id": 16, "start": 355.8, "end": 380.16, "kind": "telemetry", "title": "Readings and GPU controls", "kicker": "DETAILS", "narration": "Details shows the GPU, driver, connection and live readings: temperature, power, clocks, memory and load. Available controls include a power limit and clock offset. What you can change depends on the card and install path. The animated example values are illustrations; check the real readings on your device. The vital signs are in. Your graphics card has a better dashboard than my car.", "action": "Real Details screenshot moves upward slowly. Telemetry labels animate beside it; no invented FPS or benchmark numbers.", "reference": "README.md GPU details; plugin Details; original §8", "duration": 24.360000000000014, "note": "", "speechStart": 355.8, "speechEnd": 379.88}, {"id": 17, "start": 380.16, "end": 398.6, "kind": "xg", "title": "XG Mobile gets its own controls", "kicker": "ASUS DOCK", "narration": "On the supported ASUS XG Mobile setup, the plugin and desktop app expose the power target, fan modes, a custom fan curve, dock lighting, and core and memory offsets. These are specific dock controls, shown here with the project’s real interface. The light show is an XG Mobile booking only.", "action": "Official ASUS product photo paired with real XG screenshot. Gentle push in, then fan/light/power labels appear.", "reference": "README.md ASUS XG Mobile; screenshot-xg-mobile.png; ASUS gallery", "duration": 18.439999999999998, "note": "", "speechStart": 380.16, "speechEnd": 398.32000000000005}, {"id": 18, "start": 398.6, "end": 417.6, "kind": "desktop", "title": "The same setup on the desktop", "kicker": "DESKTOP APP", "narration": "Desktop Mode has an EGPU Buddy app and tray icon, with GPU readings, screen selection, power controls, Safe Detach and Re-attach. This screenshot uses an ASUS XG Mobile: the lighting and fan controls shown here are specific to that dock. Same show, desk seats.", "action": "Actual desktop screenshot fills right side. App icon moves down toward an illustrated tray position, labeled schematic.", "reference": "README.md Desktop app / Multiple displays; desktop screenshot", "duration": 19.0, "note": "Desktop app / tray access\nLighting and fan controls shown: ASUS XG Mobile only", "speechStart": 398.6, "speechEnd": 417.32000000000005}, {"id": 19, "start": 417.6, "end": 439.08000000000004, "kind": "experimental", "title": "Optional settings (experimental)", "kicker": "TRY WITH CARE", "narration": "NVIDIA settings adds low latency, V-sync and frame limits. AMD’s Adrenaline Settings adds supported Linux equivalents, with experimental FSR upgrades and Fluid Motion Frames for compatible games. Other opt-in extras include USB4 link checks and LG TV control. The Big Art mode menu fix is for NVIDIA only.", "action": "Three labeled text lanes appear. Experimental label stays on screen. Avoid Windows vendor control-panel screenshots.", "reference": "RELEASE-NOTES.md 0.7.236; README.md NV GPU Buddy; src/index.tsx", "duration": 21.480000000000018, "note": "", "speechStart": 417.6, "speechEnd": 438.8}, {"id": 20, "start": 439.08000000000004, "end": 464.00000000000006, "kind": "report", "title": "Save a report for Discord support", "kicker": "DISCORD SUPPORT", "narration": "For help on Discord, open EGPU Buddy and choose Show details. Under Support report, select Save support report to Desktop. Wait for it to finish. Then switch to Desktop Mode and open your Desktop folder. In the Discord support channel, attach the saved report file with a short description of the problem and what you were doing when it happened. The report does the explaining. Interpretive dance remains optional.", "action": "Highlight the source-rendered Save support report to Desktop button; show the saved file moving from Desktop to a Discord attachment step. Demo file only.", "reference": "capture-sandbox/plugin-source.tsx Support report section, makeReport; user requested Discord support workflow", "duration": 24.920000000000016, "note": "Show details → Support report → Save to Desktop → attach the file in Discord", "speechStart": 439.08000000000004, "speechEnd": 463.72}, {"id": 21, "start": 464.00000000000006, "end": 483.80000000000007, "kind": "credits", "title": "Built with testers and upstream projects", "kicker": "THANK YOU", "narration": "Thanks to the hardware testers, including SilverplayerX, 1khanfusion, RetroMann, Ivan C.nunes, zergpoop, akamel001 and Ming. Thanks also to Victor Borges for the handheld glyphs, and the projects and patch authors credited earlier. The full list is in CREDITS.md. Next, let’s install the plugin.", "action": "Tester names hold in two columns. Short upstream line, then chapter wipe into how-to. Full attribution in source files.", "reference": "CREDITS.md; original §12", "duration": 19.80000000000001, "note": "Hardware testers + patch authors + Victor Borges / handheld-controller-glyphs", "speechStart": 464.00000000000006, "speechEnd": 483.52000000000004}, {"id": 22, "start": 483.80000000000007, "end": 494.56000000000006, "kind": "tutorial", "title": "Install the Decky plugin", "kicker": "HOW TO • GAME MODE", "narration": "With Decky Loader already installed, we will add the EGPU Buddy plugin from Game Mode, then install its system integration. Those are two separate steps.", "action": "Chapter card with Decky icon and app icon. Two-stage graphic separates plugin from system integration.", "reference": "README.md Install; Decky official README", "duration": 10.759999999999991, "note": "Decky Loader already installed → EGPU Buddy plugin → system integration.", "speechStart": 483.80000000000007, "speechEnd": 494.2800000000001}, {"id": 23, "start": 494.56000000000006, "end": 506.9200000000001, "kind": "prereq", "title": "Before you start", "kicker": "STEP 1 OF 7", "narration": "This tutorial assumes Decky Loader is already installed. Start in Game Mode, with internet and power available. Keep the eGPU unplugged during installation and the reboot afterwards.", "action": "Unplugged cable graphic. Official Decky-on-device image held beside prerequisite. On-screen installer URL decky.xyz.", "reference": "README.md Install; https://github.com/SteamDeckHomebrew/decky-loader#installation", "duration": 12.360000000000014, "media": "decky-general.png", "note": "Decky Loader already installed.\nKeep eGPU unplugged through installation AND reboot.", "speechStart": 494.56000000000006, "speechEnd": 506.64000000000004}, {"duration": 15.0, "kind": "capture", "title": "1. Enable Decky Developer mode", "kicker": "EGPU BUDDY", "narration": "In Game Mode, open the Quick Access menu and select Decky. Open Decky’s settings, choose General, and turn on Developer mode. The Developer tab becomes available. This is Decky’s setting, not Steam’s separate developer menu.", "note": "Quick Access → Decky → Settings → General\nDeveloper mode: ON", "media": "decky-general.png", "reference": "Actual upstream GeneralSettings component, source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 24, "start": 506.9200000000001, "end": 521.9200000000001, "speechStart": 506.9200000000001, "speechEnd": 521.6400000000001}, {"duration": 16.519999999999982, "kind": "capture", "title": "2. Download the Decky ZIP", "kicker": "EGPU BUDDY", "narration": "The file route avoids typing a long URL. Open the project’s Releases page in a browser. Desktop Mode is the simplest place to do that. Download the EGPU-Buddy-Decky ZIP asset for the current release. Do not choose the dot run desktop installer or GitHub’s source-code ZIP.", "note": "Browser download → EGPU-Buddy-Decky-<version>.zip\nDesktop Mode is simplest; return to Game Mode afterward.", "media": "github-release-actual.png", "reference": "Actual GitHub release page read-only capture; verified release v0.7.242", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 25, "start": 521.9200000000001, "end": 538.44, "speechStart": 521.9200000000001, "speechEnd": 538.1600000000001}, {"duration": 16.519999999999982, "kind": "capture", "title": "3. Browse to the downloaded ZIP", "kicker": "EGPU BUDDY", "narration": "Return to Game Mode. In Decky settings, open Developer. Under Install Plugin from ZIP File, choose Browse. In the file picker, open your Downloads folder and select the EGPU Buddy Decky ZIP. The file route and URL route install the same plugin.", "note": "Developer → Install Plugin from ZIP File → Browse\nDownloads → EGPU-Buddy-Decky-0.7.242.zip", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source; installFromZip opens ZIP-only picker", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 26, "start": 538.44, "end": 554.96, "speechStart": 538.44, "speechEnd": 554.6800000000001}, {"duration": 16.200000000000045, "kind": "capture", "title": "4. Read Decky’s warning", "kicker": "EGPU BUDDY", "narration": "Decky shows a third-party plugin warning after Browse and before its file picker opens. Read it and check that the download came from the official project. Continue after any countdown, then select the ZIP. The URL route shows the same warning before starting its install flow.", "note": "Browse → third-party warning → Continue → file picker", "media": "decky-warning.png", "reference": "Actual upstream WarnThirdParty source-rendered sandbox; seconds=0 in capture", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 27, "start": 554.96, "end": 571.1600000000001, "speechStart": 554.96, "speechEnd": 570.88}, {"duration": 16.91999999999996, "kind": "capture", "title": "The download is in Downloads", "kicker": "EGPU BUDDY", "narration": "Select the Decky ZIP you downloaded, then confirm the selection. On a device with a different account name or browser download directory, use that location. Keep the ZIP intact; Decky reads it directly. The Downloads folder has, against all expectations, received a download.", "note": "Select the ZIP file. Do not extract it.", "media": "file-picker.png", "reference": "Reconstructed picker screenshot; path/ZIP filtering verified in Decky DeveloperSettings source", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 28, "start": 571.1600000000001, "end": 588.08, "speechStart": 571.1600000000001, "speechEnd": 587.8000000000001}, {"duration": 13.480000000000018, "kind": "capture", "title": "Confirm EGPU Buddy, then open it", "kicker": "EGPU BUDDY", "narration": "Check the plugin name and version in the installation confirmation, and install it. Once Decky finishes, return to its plugin list and open EGPU Buddy. You have installed the plugin; the system integration comes next.", "note": "Confirm plugin name and version → Install → open EGPU Buddy", "media": "plugin-confirmation.png", "reference": "Reconstructed confirmation screenshot, exact PluginInstallModal locale wording", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 29, "start": 588.08, "end": 601.5600000000001, "speechStart": 588.08, "speechEnd": 601.2800000000001}, {"duration": 14.519999999999982, "kind": "capture", "title": "Alternative: paste the direct ZIP URL", "kicker": "EGPU BUDDY", "narration": "If you already have the direct release-asset link, paste it into Install Plugin from URL and choose Install. Use the ZIP download link, rather than the release-page address. This is an alternative to browsing for the downloaded file.", "note": "Alternative path only: direct ZIP asset URL → Install", "media": "decky-developer.png", "reference": "Actual upstream DeveloperSettings source-rendered sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 30, "start": 601.5600000000001, "end": 616.08, "speechStart": 601.5600000000001, "speechEnd": 615.8000000000001}, {"duration": 19.56000000000006, "kind": "capture", "title": "5. Choose the external GPU vendor", "kicker": "EGPU BUDDY", "narration": "Press Install system integration. The next prompt asks Which GPU type will you use? Choose NVIDIA for an NVIDIA eGPU, or AMD / Intel beta for those external cards. Choose the eGPU’s vendor, even when your handheld’s built-in graphics uses another vendor.", "note": "Install system integration → external GPU vendor", "media": "install-choice.png", "reference": "Current actual plugin installClick rendered in sandbox", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 31, "start": 616.08, "end": 635.6400000000001, "speechStart": 616.08, "speechEnd": 635.36}, {"duration": 18.200000000000045, "kind": "capture", "title": "NVIDIA branch: build the patched driver", "kicker": "EGPU BUDDY", "narration": "For NVIDIA, the next confirmation is titled Install for an NVIDIA eGPU. Review the components and expected time, then continue. It installs the patched driver, the NVIDIA picture fix and the rest of the integration. Keep the charger connected and the eGPU unplugged.", "note": "NVIDIA → Install for an NVIDIA eGPU → Continue", "media": "install-confirm-nv.png", "reference": "Current confirmInstallNow with mocked NVIDIA install choice", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 32, "start": 635.6400000000001, "end": 653.8400000000001, "speechStart": 635.6400000000001, "speechEnd": 653.5600000000001}, {"duration": 26.279999999999973, "kind": "capture", "title": "AMD / Intel branch: no NVIDIA build", "kicker": "EGPU BUDDY", "narration": "For AMD or Intel, select AMD / Intel beta. The confirmation is titled Install for an AMD / Intel eGPU. The installer skips the patched NVIDIA driver and NVIDIA-only gamescope build, and installs the vendor-neutral attach, detach, fallback and audio integration. The shared confirmation still mentions NVIDIA components, but the AMD / Intel installer skips them. This path remains beta.", "note": "AMD / Intel (beta) → confirm → vendor-neutral integration\nSkips NVIDIA driver and NVIDIA-only gamescope build.", "media": "install-confirm-amd.png", "reference": "Actual prompt; install.sh GPU_VENDOR=amd gating; shared WHAT wording includes NVIDIA items even here", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 33, "start": 653.8400000000001, "end": 680.1200000000001, "speechStart": 653.8400000000001, "speechEnd": 679.8400000000001}, {"duration": 21.399999999999977, "kind": "capture", "title": "Conditional prompts: stop and read", "kicker": "EGPU BUDDY", "narration": "Your setup can add prompts. Unknown hardware can require I accept the risk. Conflicting eGPU tools can offer removal or cancellation. If Bazzite carries a built-in NVIDIA driver, use the appropriate non-NVIDIA handheld image before installing. Do not treat Continue anyway as a recommendation to ignore an incompatible image.", "note": "Conditional: untested hardware, conflicting tools, or NVIDIA image", "media": "install-untested.png", "reference": "Actual withConflictCheck / confirmInstallNow; Bazzite preflight", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 34, "start": 680.1200000000001, "end": 701.5200000000001, "speechStart": 680.1200000000001, "speechEnd": 701.2400000000001}, {"duration": 19.32000000000005, "kind": "capture", "title": "Conflicts need attention first", "kicker": "INSTALLATION • CONDITIONAL", "narration": "If a conflict prompt appears, read its identified tool or image and the evidence. Use the supported removal or image-change route. The screenshot shows the actual source-driven warning with a simulated Bazzite image conflict. Cancel rather than blindly continuing past an incompatible image.", "note": "Conflicts: read evidence and resolve before continuing.", "media": "install-conflict.png", "reference": "withConflictCheck; simulated Bazzite NVIDIA image state", "id": 35, "start": 701.5200000000001, "end": 720.8400000000001, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 701.5200000000001, "speechEnd": 720.5600000000001}, {"duration": 21.24000000000001, "kind": "capture", "title": "6. Wait for integration to finish", "kicker": "EGPU BUDDY", "narration": "The NVIDIA path can take several minutes while the driver builds. The AMD / Intel path skips that build. Read the actual progress and result rather than using the animation’s elapsed time. You can close the menu while work continues, and the plugin reports completion. The progress bar cannot be hurried by staring at it. We have tried.", "note": "NVIDIA: patched driver build\nAMD / Intel: no NVIDIA build", "media": "install-progress-nv.png", "reference": "Actual Progress component with mocked progress; no installation executed", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 36, "start": 720.8400000000001, "end": 742.0800000000002, "speechStart": 720.8400000000001, "speechEnd": 741.8000000000002}, {"duration": 12.759999999999991, "kind": "capture", "title": "The AMD / Intel progress path", "kicker": "EGPU BUDDY", "narration": "Here is the same progress interface on the AMD / Intel branch. The capture uses a mocked installation step, so it demonstrates the layout rather than a successful hardware test. Follow the result on your own device.", "note": "AMD / Intel example • simulated progress, not a device test", "media": "install-progress-amd.png", "reference": "Current actual plugin with mocked AMD setup state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 37, "start": 742.0800000000002, "end": 754.8400000000001, "speechStart": 742.0800000000002, "speechEnd": 754.5600000000002}, {"duration": 15.960000000000036, "kind": "capture", "title": "If installation fails, repair first", "kicker": "INSTALLATION • ERROR PATH", "narration": "An installation error is not the success screen. Keep the eGPU unplugged, read the message and log location, and use the displayed Repair route. Resume the reboot and first-connect steps only after the integration reports success.", "note": "Error → keep eGPU unplugged → Repair / inspect log", "media": "install-error.png", "reference": "Current su.rc error path rendered with mocked rc20", "id": 38, "start": 754.8400000000001, "end": 770.8000000000002, "action": "Show the current reference visual, with an animated focus and timed caption.", "speechStart": 754.8400000000001, "speechEnd": 770.5200000000001}, {"duration": 17.879999999999995, "kind": "capture", "title": "7. Reboot before connecting the eGPU", "kicker": "EGPU BUDDY", "narration": "When installation reports success, choose Reboot the system. Keep the eGPU unplugged throughout that reboot. The required kernel protections are not active until then. If an error appears, leave the eGPU unplugged and follow Repair or the displayed message before proceeding.", "note": "Success → Reboot the system\neGPU stays unplugged through reboot.", "media": "install-success.png", "reference": "Actual su.rc=0 / needs_reboot UI; mocked success state", "action": "Animate the illustrated signal path or show the referenced capture with progressive focus.", "id": 39, "start": 770.8000000000002, "end": 788.6800000000002, "speechStart": 770.8000000000002, "speechEnd": 788.4000000000002}, {"id": 40, "start": 788.6800000000002, "end": 810.5600000000002, "kind": "finish", "title": "Connect after the reboot", "kicker": "STEP 7 OF 7", "narration": "Once Game Mode is back, connect the eGPU and check its status in EGPU Buddy. Your setup is ready for its first test. You’ll find the downloads, tested hardware list and full instructions on GitHub, with the Discord link below. See you on the big screen. That's our show. Keep your frame times steady and your snack supply overclocked.", "action": "Reconnect topology, then GitHub and Discord end card. User footage can reprise behind final labels.", "reference": "README.md Install / Reporting problems; Original §13", "duration": 21.879999999999995, "note": "After reboot: connect, inspect status, then test your setup.", "speechStart": 788.6800000000002, "speechEnd": 810.2800000000002}], "audio": "radio-voice.mp3?v=radio-06", "script": "script-radio.txt"}};
